:root {
  color-scheme: light;
  --bg: oklch(0.975 0.006 160);
  --surface: oklch(1 0 0);
  --head: oklch(0.955 0.008 160);
  --line: oklch(0.91 0.006 160);    /* dividers only, carries no meaning */
  --edge: oklch(0.60 0.012 160);    /* control borders, 3.7:1 on bg */
  --ink: oklch(0.23 0.015 160);
  --muted: oklch(0.47 0.015 160);   /* 6.3:1 on bg */
  --accent: oklch(0.46 0.09 160);
  --accent-press: oklch(0.38 0.08 160);
  --danger: oklch(0.50 0.17 27);
  --ring: var(--accent);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --radius-panel: 10px;
  --radius-control: 6px;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 1rem/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
  caret-color: var(--accent);
}

::selection { background: oklch(0.88 0.06 160); }

h1, h2 { margin: 0; text-wrap: balance; }
p { margin: 0; }

a, button, input, [tabindex] { -webkit-tap-highlight-color: transparent; }

:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.wrap {
  max-width: 72rem;
  margin-inline: auto;
  padding-inline: 1.25rem;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.skip {
  position: absolute;
  inset-inline-start: 1rem;
  top: -3rem;
  padding: 0.5rem 0.75rem;
  background: var(--surface);
  color: var(--ink);
  border-radius: var(--radius-control);
  z-index: 30;
}
.skip:focus { top: 0.75rem; }

/* ---------- Status mark: the one device. Fill = how settled, colour = urgency. ---------- */

.mark {
  display: inline-block;
  flex: none;
  width: 0.75em;
  height: 0.75em;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  vertical-align: -0.05em;
}
.mark.draft   { color: var(--muted); }
.mark.sent    { color: var(--accent); background: linear-gradient(90deg, currentColor 50%, transparent 50%); }
.mark.paid    { color: var(--accent); background: currentColor; }
.mark.overdue { color: var(--danger); background: linear-gradient(90deg, currentColor 50%, transparent 50%); }

/* ---------- Header + What's new ---------- */

.top {
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}

.top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 3.5rem;
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: -0.01em;
}
.wordmark::before {
  content: "";
  width: 0.8em; height: 0.8em;
  border-radius: 50%;
  border: 2px solid var(--accent);
  background: linear-gradient(90deg, var(--accent) 50%, transparent 50%);
}

.ghost {
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-control);
  min-height: 2.25rem;
  padding: 0.25rem 0.75rem;
  cursor: pointer;
  touch-action: manipulation;
}
.ghost:active { background: var(--head); }
.ghost[aria-expanded="true"] { background: var(--head); border-color: var(--line); }
@media (hover: hover) {
  .ghost:hover { background: var(--head); }
}

/* Disclosure panel: grid rows 0fr -> 1fr so it opens to its natural height. */
.news {
  display: grid;
  grid-template-rows: 0fr;
  visibility: hidden;
  opacity: 0;
  transition:
    grid-template-rows 180ms var(--ease),
    opacity 180ms var(--ease),
    visibility 0s 180ms;
}
.news.open {
  grid-template-rows: 1fr;
  visibility: visible;
  opacity: 1;
  transition:
    grid-template-rows 240ms var(--ease),
    opacity 240ms var(--ease),
    visibility 0s;
}
.news-clip { overflow: hidden; min-height: 0; }
.news-body {
  padding-block: 1.25rem 1.5rem;
  border-top: 1px solid var(--line);
}
.news-body h2 { font-size: 1rem; margin-bottom: 0.5rem; }
.news-body ul {
  margin: 0;
  padding-inline-start: 1.1rem;
  display: grid;
  gap: 0.375rem;
  max-width: 70ch;
}

/* ---------- Hero + form ---------- */

.intro {
  display: grid;
  gap: 2.5rem;
  padding-block: 3rem 2.5rem;
}
@media (min-width: 56rem) {
  .intro {
    grid-template-columns: minmax(0, 1fr) 23rem;
    gap: 4rem;
    align-items: center;
    padding-block: 4.5rem 3.5rem;
  }
}

.hero h1 {
  font-size: 1.728rem;
  line-height: 1.15;
  letter-spacing: -0.02em;
  max-width: 20ch;
}
@media (min-width: 56rem) {
  .hero h1 { font-size: 2.488rem; }
}

.sub {
  margin-top: 1rem;
  font-size: 20px;    /* per brief: fixed 20px, regular weight, so it is body text and needs 4.5:1 */
  line-height: 1.5;
  color: var(--muted);
  max-width: 36ch;
  text-wrap: pretty;
}

.signin {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-panel);
  padding: 1.5rem;
  display: grid;
  gap: 1rem;
  box-shadow: 0 1px 2px oklch(0.23 0.015 160 / 0.06), 0 8px 24px -12px oklch(0.23 0.015 160 / 0.12);
}
.signin h2 { font-size: 1.2rem; margin-bottom: 0.25rem; }

.field { display: grid; gap: 0.375rem; }
.field label { font-size: 0.875rem; font-weight: 600; }

input[type="email"], input[type="password"], input[type="text"] {
  width: 100%;
  min-width: 0;
  font: inherit;
  font-size: 1rem;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--edge);
  border-radius: var(--radius-control);
  min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
}
input:focus-visible { outline-offset: 1px; }
input[aria-invalid="true"] { border-color: var(--danger); box-shadow: inset 0 0 0 1px var(--danger); }

.pw { position: relative; }
.pw input { padding-inline-end: 4.5rem; }
.reveal {
  position: absolute;
  inset-block: 0.25rem;
  inset-inline-end: 0.25rem;
  min-height: 0;
}

.error {
  font-size: 0.875rem;
  color: var(--danger);
}
.error:empty { display: none; }

.check {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9375rem;
  min-height: 1.75rem;
  width: fit-content;
  cursor: pointer;
}
.check input {
  width: 1.125rem;
  height: 1.125rem;
  margin: 0;
  accent-color: var(--accent);
}

.primary {
  font: inherit;
  font-weight: 600;
  color: var(--surface);
  background: var(--accent);
  border: 0;
  border-radius: var(--radius-control);
  min-height: 2.75rem;
  padding: 0.5rem 1rem;
  cursor: pointer;
  touch-action: manipulation;
  transition: background-color 150ms var(--ease);
}
.primary:active { background: var(--accent-press); transition-duration: 0ms; }
.primary[aria-disabled="true"] { cursor: progress; background: var(--accent-press); }
@media (hover: hover) {
  .primary:hover { background: var(--accent-press); }
}

/* Reserve one line so a message never shifts the form. */
.status {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  min-height: 1.5rem;
  font-size: 0.875rem;
}
.status[data-state="error"] { color: var(--danger); }
.status[data-state]::before {
  content: "";
  flex: none;
  width: 0.75em; height: 0.75em;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  background: linear-gradient(90deg, currentColor 50%, transparent 50%);
}
.status[data-state="pending"] { color: var(--accent); }

/* ---------- Invoice preview ---------- */

.preview { padding-bottom: 4rem; }

.preview-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.25rem 1rem;
  margin-bottom: 0.75rem;
}
.preview-head h2 { font-size: 1.2rem; }
.note { font-size: 0.875rem; color: var(--muted); }

.scroller {
  max-height: min(38rem, 75dvh);
  overflow: auto;
  overscroll-behavior: contain;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-panel);
  scroll-padding-top: 2.25rem;       /* >= sticky header height */
  scroll-padding-inline-start: 11rem; /* >= sticky first column */
}

table {
  width: 100%;
  min-width: 46rem;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
}
.c-client { width: 26%; }
.c-num    { width: 7rem; }
.c-date   { width: 7.5rem; }
.c-amt    { width: 8rem; }
.c-status { width: 11rem; }

th, td {
  text-align: start;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-bottom: 1px solid var(--line);
}
td { padding: 0.3125rem 0.75rem; height: 1.875rem; }
.num { text-align: end; }

thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--head);
  padding: 0;
  font-weight: 600;
}
th:first-child, td:first-child {
  position: sticky;
  inset-inline-start: 0;
  z-index: 1;
  background: var(--surface);
  border-inline-end: 1px solid var(--line);
}
thead th:first-child { z-index: 3; background: var(--head); }

th button {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  width: 100%;
  min-height: 2.25rem;
  padding: 0.375rem 0.75rem;
  font: inherit;
  color: var(--ink);
  text-align: inherit;
  background: none;
  border: 0;
  cursor: pointer;
}
th.num button { justify-content: flex-end; }
th button::after {
  content: "↕" / "";
  color: var(--muted);
  font-weight: 400;
}
th[aria-sort="ascending"] button::after  { content: "↑" / ""; color: var(--ink); }
th[aria-sort="descending"] button::after { content: "↓" / ""; color: var(--ink); }
@media (hover: hover) {
  th button:hover { background: var(--line); }
}
th button:active { background: var(--line); }

/* Inside the clipped scroller the ring sits inset so it is never cut off. */
.scroller :focus-visible { outline-offset: -2px; }

@media (hover: hover) {
  tbody tr:hover td { background: var(--head); }
}

.client { font-weight: 500; }
.nodate { color: var(--muted); }

.state { display: inline-flex; align-items: center; gap: 0.4rem; }
.state.overdue { color: var(--danger); font-weight: 500; }
.late { font-weight: 400; }

/* ---------- Reduced motion: keep the open/closed state, drop the movement ---------- */

@media (prefers-reduced-motion: reduce) {
  .news, .news.open {
    transition-property: opacity, visibility;
    transition-duration: 120ms, 0s;
  }
  .news { transition-delay: 0s, 120ms; }
}

@media (prefers-contrast: more) {
  :root { --line: var(--edge); --muted: oklch(0.38 0.015 160); }
}

