// ---------- What's new ----------

const newsToggle = document.getElementById('news-toggle');
const news = document.getElementById('news');

function setNews(open) {
  newsToggle.setAttribute('aria-expanded', open);
  news.classList.toggle('open', open);
}
newsToggle.addEventListener('click', () => setNews(newsToggle.getAttribute('aria-expanded') !== 'true'));
document.querySelector('.top').addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && news.classList.contains('open')) {
    setNews(false);
    newsToggle.focus();
  }
});

// ---------- Sign in ----------

const form = document.getElementById('signin');
const submit = document.getElementById('submit');
const status = document.getElementById('status');
const reveal = document.getElementById('reveal');
const fields = [form.elements.email, form.elements.password];

reveal.innerHTML = 'Show<span class="sr-only"> password</span>';
reveal.addEventListener('click', () => {
  const pw = form.elements.password;
  const show = pw.type === 'password';
  pw.type = show ? 'text' : 'password';
  reveal.innerHTML = (show ? 'Hide' : 'Show') + '<span class="sr-only"> password</span>';
});

function message(input) {
  if (input.name === 'email') {
    if (!input.value.trim()) return 'Enter your email address.';
    if (input.validity.typeMismatch) return 'Enter an email address in the format name@yourfirm.com.';
  }
  if (input.name === 'password' && !input.value) return 'Enter your password.';
  return '';
}

function check(input) {
  const msg = message(input);
  document.getElementById(input.id + '-error').textContent = msg;
  input.toggleAttribute('aria-invalid', !!msg);
  if (msg) input.setAttribute('aria-invalid', 'true');
  return !msg;
}

function setStatus(state, text) {
  if (state) status.dataset.state = state; else delete status.dataset.state;
  status.textContent = text;
}

for (const input of fields) {
  // Blur only validates a field the person actually typed in; once it shows an error, fix it live.
  input.addEventListener('input', () => {
    input.dataset.dirty = '1';
    if (input.hasAttribute('aria-invalid')) check(input);
  });
  input.addEventListener('blur', () => { if (input.dataset.dirty) check(input); });
}

let inFlight = false;

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  if (inFlight) return;

  const bad = fields.filter((f) => !check(f));
  if (bad.length) {
    setStatus('error', bad.length === 1 ? 'One field needs attention.' : `${bad.length} fields need attention.`);
    bad[0].focus();
    return;
  }

  inFlight = true;
  submit.setAttribute('aria-disabled', 'true');
  submit.textContent = 'Signing in…';
  setStatus('pending', 'Checking your details…');

  try {
    const res = await fetch(form.action, { method: 'POST', body: new FormData(form), credentials: 'same-origin' });
    if (res.ok) {
      setStatus('pending', 'Signed in. Opening your invoices…');
      location.assign(res.redirected ? res.url : '/');
      return;
    }
    setStatus('error', res.status === 401
      ? "That email and password don't match. Check them and try again."
      : `Sign-in isn't available right now (error ${res.status}). Try again in a few minutes.`);
  } catch {
    setStatus('error', "We couldn't reach Tallyhouse. Check your connection and try again.");
  }
  inFlight = false;
  submit.removeAttribute('aria-disabled');
  submit.textContent = 'Sign in';
});

// ---------- Invoice preview (sample data) ----------

// ponytail: fixed "as of" date so the sample reads the same for everyone; real data replaces all of this.
const AS_OF = new Date(2026, 8, 24);
const DAY = 86400000;
const CLIENTS = [
  'Harbour Street Bakery', 'Okafor & Lindqvist Architects', 'Pinewood Veterinary Clinic',
  'Castleford Joinery', 'Blue Heron Physiotherapy', 'Marlow Print Works', 'Northgate Dental',
  'Ferris Wheel Events', 'Quayside Coffee Roasters', 'Ashdown Landscaping', 'Tamsin Reyes Photography',
  'Kettle & Crane Brewing',
];

// Seeded so the sample is stable across reloads.
let seed = 7;
const rand = () => (seed = (seed * 16807) % 2147483647) / 2147483647;

const invoices = Array.from({ length: 40 }, (_, i) => {
  const client = CLIENTS[Math.floor(rand() * CLIENTS.length)];
  const created = new Date(AS_OF - (i * 2 + Math.floor(rand() * 2)) * DAY);
  const terms = rand() < 0.6 ? 30 : 14;
  const amount = Math.round((150 + rand() * 9500) * 100) / 100;
  const number = `INV-${String(2481 - i)}`;
  if (i < 3) return { client, number, issued: null, due: null, amount, status: 'draft', late: 0 };
  const due = new Date(+created + terms * DAY);
  const late = Math.round((AS_OF - due) / DAY);
  const paid = i > 8 && rand() < 0.7;
  const status = paid ? 'paid' : late > 0 ? 'overdue' : 'sent';
  return { client, number, issued: created, due, amount, status, late: status === 'overdue' ? late : 0 };
});

const money = new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' });
const date = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
const plural = new Intl.PluralRules(undefined);
const LABEL = { draft: 'Draft', sent: 'Sent', paid: 'Paid', overdue: 'Overdue' };
// Status sorts by urgency: most overdue first, paid last.
const RANK = { overdue: 0, sent: 1, draft: 2, paid: 3 };

const sorters = {
  client: (a, b) => a.client.localeCompare(b.client),
  number: (a, b) => a.number.localeCompare(b.number, undefined, { numeric: true }),
  issued: (a, b) => a.issued - b.issued,
  due: (a, b) => a.due - b.due,
  amount: (a, b) => a.amount - b.amount,
  status: (a, b) => RANK[a.status] - RANK[b.status] || b.late - a.late,
};

document.getElementById('asof').textContent = date.format(AS_OF);
document.getElementById('count').textContent = `${invoices.length} invoices`;

const tbody = document.getElementById('rows');
const headers = [...document.querySelectorAll('th[data-key]')];
const sortStatus = document.getElementById('sort-status');

const cellDate = (d) => (d ? date.format(d) : '<span class="nodate">Not sent</span>');
const cellStatus = (inv) => {
  const late = inv.late ? ` <span class="late">· ${inv.late} ${plural.select(inv.late) === 'one' ? 'day' : 'days'} late</span>` : '';
  return `<span class="state ${inv.status}"><span class="mark ${inv.status}" aria-hidden="true"></span>${LABEL[inv.status]}${late}</span>`;
};

function render(key, dir) {
  const cmp = sorters[key];
  const nullsLast = (a, b) => (a[key] === null) - (b[key] === null);
  const rows = [...invoices].sort((a, b) => nullsLast(a, b) || (dir === 'descending' ? -cmp(a, b) : cmp(a, b)));
  tbody.innerHTML = rows.map((inv) => `<tr>
    <td class="client" title="${inv.client}">${inv.client}</td>
    <td>${inv.number}</td>
    <td>${cellDate(inv.issued)}</td>
    <td>${cellDate(inv.due)}</td>
    <td class="num">${money.format(inv.amount)}</td>
    <td>${cellStatus(inv)}</td>
  </tr>`).join('');
  for (const th of headers) {
    if (th.dataset.key === key) th.setAttribute('aria-sort', dir); else th.removeAttribute('aria-sort');
  }
}

function sortBy(key, dir, announce) {
  render(key, dir);
  const params = new URLSearchParams(location.search);
  params.set('sort', key);
  params.set('dir', dir === 'descending' ? 'desc' : 'asc');
  history.replaceState(null, '', `?${params}`);
  if (announce) {
    const name = headers.find((th) => th.dataset.key === key).textContent.trim();
    sortStatus.textContent = `Sorted by ${name}, ${dir}.`;
  }
}

for (const th of headers) {
  th.querySelector('button').addEventListener('click', () => {
    const same = th.hasAttribute('aria-sort');
    const dir = same && th.getAttribute('aria-sort') === 'ascending' ? 'descending' : 'ascending';
    sortBy(th.dataset.key, same ? dir : 'ascending', true);
  });
}

const params = new URLSearchParams(location.search);
const startKey = sorters[params.get('sort')] ? params.get('sort') : 'issued';
const startDir = params.get('dir') === 'asc' ? 'ascending' : params.has('dir') ? 'descending' : 'descending';
render(startKey, params.get('sort') ? startDir : 'descending');

